mapper.select:
SELECT 
FROM cms_comment c
LEFT JOIN cms_article a ON a.id = c.article_id
LEFT JOIN sys_user u ON u.id = c.user_id
LEFT JOIN sys_user ru ON ru.id = c.reply_user_id

    AND c.article_id = #{articleId}
    AND c.status = #{status}
    AND c.ai_status = #{aiStatus}

        AND (c.content LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY c.id DESC
